from common62 import *
import numpy as np,csv,collections
e=read(OUT/'EVALUATION62_V1.json');v=read(OUT/'INDEPENDENT_REPLAY62_V1.json');assert v['status']=='PASS';q=read(OUT/'QUALIFICATION62_V1.json')
fits=[read(p) for p in sorted(OUT.glob('*_fit62_v1.json'))];assert len(fits)==9
group=collections.defaultdict(list)
for r in e['rows']:group[(r['arm'],r['view'],r['horizon'])].append(r)
summary=[]
for (arm,view,h),rr in sorted(group.items()):
 byseed=collections.defaultdict(list)
 for r in rr:byseed[r['training_seed']].append(r)
 seed_means=[np.mean([r['mse'] for r in ss]) for ss in byseed.values()]
 seed_mae=[np.mean([r['mae'] for r in ss]) for ss in byseed.values()]
 summary.append({'arm':arm,'view':view,'horizon':h,'origins':rr[0]['origins'],'training_seeds':len(byseed) if None not in byseed else 0,'mse':float(np.mean(seed_means)),'mse_seed_std':float(np.std(seed_means,ddof=1)) if len(seed_means)>1 else None,'mae':float(np.mean(seed_mae)),'inference_mse_rng_std_mean':float(np.mean([np.std([r['mse'] for r in ss],ddof=1) for ss in byseed.values()])) if None not in byseed else None})
def cell(arm,view,h):return next(r for r in summary if (r['arm'],r['view'],r['horizon'])==(arm,view,h))
rankings={}
for view,h in [('official96',96),('common384',96),('common384',192),('common384',384)]:rankings[view+'_'+str(h)]=[r['arm'] for r in sorted([r for r in summary if r['view']==view and r['horizon']==h],key=lambda r:r['mse'])]
changes=rankings['common384_96']!=rankings['common384_384']
result={'utc':utc(),'status':'CLOSED_EXPLORATORY_REPRODUCTION','decision':'NO_NEW_RESEARCH_DIRECTION_ESTABLISHED','accepted_final_directions':0,'formal_fit_count':9,'formal_updates':sum(r['formal_optimizer_updates'] for r in fits),'aborted_runtime_attempts':2,'aborted_updates_last_recorded_lower_bound':3200,'training_seconds':sum(r['training_seconds'] for r in fits),'summary':summary,'rankings':rankings,'common_origin_rank_change':changes,'native_roll_replay_max_raw':max(r['native_vs_independent_roll_max_raw_difference'] for r in e['native_vs_independent_roll']),'metric_replay_max_mse':v['max_mse_difference'],'evaluation_sha256':sha(OUT/'EVALUATION62_V1.json'),'replay_sha256':sha(OUT/'INDEPENDENT_REPLAY62_V1.json'),'protocol_sha256':sha(ROOT/'PROTOCOL62_V1.md')}
dump(OUT/'SUMMARY62_V1.json',result)
with (OUT/'SUMMARY62_V1.csv').open('x',newline='',encoding='utf-8') as f:
 w=csv.DictWriter(f,fieldnames=list(summary[0]));w.writeheader();w.writerows(summary)
table='| Arm | View / horizon | Origins | MSE | Seed SD | MAE |\n|---|---|---:|---:|---:|---:|\n'
for r in summary:table+=f"| {r['arm']} | {r['view']} / {r['horizon']} | {r['origins']} | {r['mse']:.7f} | {r['mse_seed_std'] if r['mse_seed_std'] is not None else 'n/a'} | {r['mae']:.7f} |\n"
evidence=f"Nine native fits, {result['formal_updates']} successful-fit optimizer updates, plus two aborted native attempts with at least3200 recorded updates (exact final count unavailable), {result['training_seconds']:.1f} seconds of successful-fit training. Four fits use the unchanged native loader; five use a cached-tensor data-copy compatibility wrapper qualified with128 bitwise window comparisons, identical forward/gradients and180000 stress lookups. One per-window-copy diagnostic failed and is retained. Three training seeds, three fixed inference RNG streams. Native block-loop replay maximum raw-unit difference {result['native_roll_replay_max_raw']:.4g}; all {v['metric_rows']} metric rows replayed, MSE difference at most {v['max_mse_difference']:.4g}. All selected/terminal weight and prediction hashes verified."
boundary='ETTh1 is one previously examined measured system, with overlapping evaluation windows. Training seeds are initialization repeats, not independent systems. This is an exploratory screen. Inference RNG variation comes from native ProbAttention sampling; it is not learned predictive uncertainty. Extended point error alone does not establish incorrect physical dynamics. The source task makes no causal intervention guarantee.'
decision='No new research direction is established. Do not call a rank change a novel mechanism. Existing multistep system identification, state-space simulation and dynamical-system reconstruction are necessary next controls if a residual failure merits further study.'
reports={
'README.md':'# C62 native PRO-DYN reproduction and rollout screen\n\n'+evidence+'\n\n'+decision+'\n\nSee experimental_results.md, PROTOCOL62_V1.md and outputs/SUMMARY62_V1.json. Raw arrays and weights remain on the server G disk; no local result synchronization.\n',
'literature_review.md':'# Literature and novelty boundary\n\n[PRO-DYN source](https://github.com/ARBrachet/PRO-DYN/tree/733d986d349e9e71ded5d9cdeeeed8d3323d83b4) supplies the exact model variants and training defaults. [The authors’ project](https://arbrachet.github.io/PRO-DYN/) defines temporal propagation blocks in forecasting; the code experiment here is not a numerical reproduction of the complete paper tables. Original upstream files remain unchanged and are recorded by Git blob/SHA256, but are not republished because this pinned repository contains no license file.\n\nSubsystem reuse is already studied in [Neary and Topcu](https://arxiv.org/abs/2212.00893) and [input-output subsystem identification](https://arxiv.org/abs/2411.05730). [C-PHAST](https://shubham-bhardwaj.com/cphast/) also explicitly exposes block recomposition and target-specific wiring. These are source-scope checks, not executed baselines or proof that every partially observed composition problem is solved. Generic module composition is therefore not accepted as a new idea.\n\n'+decision+'\n',
'baseline_registry.md':'# Baseline registry\n\nSource: PRO-DYN 733d986d349e9e71ded5d9cdeeeed8d3323d83b4. Native unchanged Informer/Informer_PRO/Informer_DYN models, optimizer, scheduler, validation, early stopping and block forecasting executed. The adapter is loaded through namespace packages to avoid unrelated eager imports; NumPy Inf alias restores a removed constant. The full TFB CLI/report layer was not executed. Official ETTh1 H96 hyperparameters were used.\n\n'+evidence+'\n\nThree ordinary controls: persistence, seasonal-24 and validation-selected direct ridge, implemented for this audit. No new WorldTS or LatentTSF fit in this cycle. No PHNN/C-PHAST execution.\n\n'+boundary+'\n',
'experimental_results.md':'# Experimental results\n\n'+evidence+'\n\nAll metrics are train-standardized; values averaged over inference RNG within seed then training seeds. The common384 views use identical start origins. Official96 uses every permissible origin; it is not directly paired with the smaller common-origin set.\n\n'+table+'\n\nRankings: '+json.dumps(rankings)+'\n\n'+boundary+'\n',
'negative_evidence.md':'# Negative evidence and limitations\n\n'+decision+'\n\n'+boundary+'\n\nNative model equality is checked on training-only histories before test scoring. Correct native training and a matching independent rollout loop rule out our loop implementation as an explanation of scored differences within stated tolerances; they do not prove convergence, correct stochastic simulation, or absence of future architecture bugs. Native maximum ten epochs and native validation selection are preserved. A stronger trained state-space model is not fitted in this cycle.\n',
'hypothesis_space.md':'# Competing explanations\n\n1. Finite-horizon optimization: longer rollouts change the use case; compare competent native multistep SSM training before attributing a deficit to missing model state.\n2. Interface error: native batch rolling and an independent same-core loop must agree; pre-test training-history checks are retained.\n3. Random approximate attention: report three fixed inference RNG streams separately from training-seed variation.\n4. Ordinary inductive bias: ridge and seasonal controls may outperform neural arms without requiring a new mechanism.\n5. Genuine missing capability: requires an independent mechanism/dataset and matched information/budget controls; this screen does not establish it.\n',
'research_ideas.md':'# Candidate research questions\n\nA conditional question remains: when does a finite-horizon forecast serve as a reusable autonomous simulator? This is an established broad problem, not an accepted novel direction. C62 supplies a native baseline qualification and a small code-protocol reproduction. Any next experiment needs a concrete residual beyond proper multistep SSM/DSR training, not simply a longer horizon where error increases.\n\n'+decision+'\n',
'final_research_direction.md':'# Research disposition\n\n**Research Question:** Does the official PRO-DYN H96 forecasting comparison preserve its relative behavior under native longer block rollout?\n\n**Evidence:** '+evidence+'\n\n'+table+'\n\n**Existing Methods:** Direct ridge, seasonal prediction, multistep system identification and dynamical-system reconstruction must be distinguished from a new framework.\n\n**Proposed Idea:** None accepted from C62.\n\n**Falsification:** A deficit removed by ordinary controls or correct training/interface cannot justify a new architecture. No test-set rescue tuning is performed.\n\n**Feasibility:** Nine native fits executed on one RTX5090, pinned original source and original ETTh1 blob.\n\n**Next Experiment:** Select an independent, source-grounded residual capability after comparison with competent state-space/DSR controls. Do not rerun this test set to choose a loss.\n\n'+boundary+'\n\nOverall discovery remains ACTIVE_UNACHIEVED; accepted final directions: 0.\n'
}
for name,text in reports.items():
 with (ROOT/name).open('x',encoding='utf-8') as f:f.write(text)
dump(OUT/'CLOSURE62_V1.json',{'utc':utc(),'status':'CLOSED','summary_sha256':sha(OUT/'SUMMARY62_V1.json'),'reports':{name:sha(ROOT/name) for name in reports},'accepted_final_directions':0,'formal_fit_count':9,'formal_updates':result['formal_updates']})
print(json.dumps({'status':'CLOSED','decision':result['decision'],'rankings':rankings,'formal_updates':result['formal_updates']}))
